```python
 
def blob_matches_filter(blob: Blob,  kind__eq: EventKind | None, timestamp__gte: datetime | None,
        timestamp__lt: datetime | None) -> Bool:
            filename = self._get_filename_from_blob(blob)
            filename_info = self._parse_filename(filename)
            if not filename_info:
                return False

            if kind__eq and filename_info['kind'] != kind__eq:
