```typescript
getNextPageParam: (lastPage, allPages, lastPageParam) => {
  if (useInstallationRepos && installations) {
    const { installationIndex, pageId } = lastPageParam as { installationIndex: number; pageId: string | null };

    // If there's a next page in current installation, use it
    if (lastPage.next_page_id) {
      return { installationIndex, pageId: lastPage.next_page_id };
    }

    // Otherwise, advance to next installation if available
    if (installationIndex + 1 < installations.length) {
      return { installationIndex: installationIndex + 1, pageId: null };
    }
  }

  // For non-installation repos or no more data
  return lastPage.next_page_id;
}
```

