// In use-upsert-secret.ts
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { SecretsService } from "#/api/secrets-service";

export const useUpsertSecret = () => {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ name, value, description }: { name: string; value: string; description?: string }) =>
      SecretsService.upsertSecret(name, value, description),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["secrets"] });
    },
  });
};

// Then in this component:
