  { name: CLAUDE_CREDENTIALS_SECRET_NAME, value: claudeCredentials.trim(), description: "..." },
  { onSuccess: () => { setClaudeCredentials(""); refetchFileSecrets(); }, onError: () => { displayErrorToast(...); } }
);
```

